SELECT  FROM flash_sale_campaigns c
WHERE c.id = #{id}
FOR UPDATE SKIP LOCKED

SELECT id FROM flash_sale_campaigns
WHERE status = 'SCHEDULED' AND warmed_up_at IS NULL
  AND start_time <= #{until} AND end_time > #{now}
ORDER BY start_time
LIMIT #{limit}

SELECT id FROM flash_sale_campaigns
WHERE status = 'SCHEDULED' AND warmed_up_at IS NOT NULL
  AND start_time <= #{now} AND end_time > #{now}
ORDER BY start_time
LIMIT #{limit}

SELECT id FROM flash_sale_campaigns
WHERE status IN ('SCHEDULED', 'RUNNING') AND end_time <= #{now}
ORDER BY end_time
LIMIT #{limit}

mapper.update:
UPDATE flash_sale_campaigns
SET name = #{name}, start_time = #{startTime}, end_time = #{endTime}
WHERE id = #{id}
